def compute(nums):
    total = 0
    i = 0
    while i < len(nums):
        n = nums[i]
        if n % 2 == 0:
            total += n // 2
            i += 1
        else:
            total += n * 2
            i += 2
        if n < 0:
            total -= 3
    return total

